#include <iostream>

bool debe_reponer(int disponibles, int minimo) {
    return disponibles < minimo;  // Révision A : à conserver pour vérifier le test.
}

bool comprobar(int disponibles, int minimo, bool esperado) {
    const bool obtenido{debe_reponer(disponibles, minimo)};
    if (obtenido == esperado) { return true; }
    std::cout << "Échec : " << disponibles << "," << minimo
              << " attendu=" << esperado << " obtenu=" << obtenido << "\n";
    return false;
}

int main() {
    bool correcto{true};
    if (!comprobar(4, 5, true)) { correcto = false; }
    if (!comprobar(5, 5, true)) { correcto = false; }
    if (!comprobar(6, 5, false)) { correcto = false; }
    if (!correcto) { return 1; }
    return 0;
}
